"""User-entered maintenance records (never generated by data sources)."""

from __future__ import annotations

from collections.abc import Callable
from datetime import datetime

from sqlalchemy import select
from sqlalchemy.orm import Session

from src.core.validation import validate_maintenance_fields
from src.models.orm import Anomaly, Machine, MaintenanceEvent
from src.models.schemas import NotFoundError, ValidationFailed, ValidationIssue
from src.utils.time_utils import Window, utc_now


class MaintenanceService:
    def __init__(self, session: Session, clock: Callable[[], datetime] = utc_now):
        self.session = session
        self.clock = clock

    def _validate(self, machine_id: str, related_anomaly_id: int | None, **fields) -> dict:
        clean, issues = validate_maintenance_fields(now=self.clock(), **fields)
        if self.session.get(Machine, machine_id) is None:
            issues.append(ValidationIssue("UNKNOWN_MACHINE", "machine_id", "Select an existing machine."))
        if related_anomaly_id is not None:
            anomaly = self.session.get(Anomaly, related_anomaly_id)
            if anomaly is None or anomaly.machine_id != machine_id:
                issues.append(
                    ValidationIssue(
                        "INVALID_ANOMALY", "related_anomaly_id",
                        "The linked anomaly must exist and belong to the same machine.",
                    )
                )
        if issues:
            raise ValidationFailed(issues)
        return clean

    def create(
        self,
        *,
        machine_id: str,
        event_type: str,
        start_time: datetime | None,
        description: str,
        end_time: datetime | None = None,
        finding: str | None = None,
        responsible: str | None = None,
        notes: str | None = None,
        related_anomaly_id: int | None = None,
    ) -> MaintenanceEvent:
        clean = self._validate(
            machine_id, related_anomaly_id, event_type=event_type, start_time=start_time,
            end_time=end_time, description=description, finding=finding,
            responsible=responsible, notes=notes,
        )
        now = self.clock()
        record = MaintenanceEvent(
            machine_id=machine_id, related_anomaly_id=related_anomaly_id,
            created_at=now, updated_at=now, **clean,
        )
        self.session.add(record)
        self.session.flush()
        return record

    def update(
        self,
        record_id: int,
        *,
        event_type: str,
        start_time: datetime | None,
        description: str,
        end_time: datetime | None = None,
        finding: str | None = None,
        responsible: str | None = None,
        notes: str | None = None,
        related_anomaly_id: int | None = None,
    ) -> MaintenanceEvent:
        record = self.get(record_id)
        clean = self._validate(
            record.machine_id, related_anomaly_id, event_type=event_type, start_time=start_time,
            end_time=end_time, description=description, finding=finding,
            responsible=responsible, notes=notes,
        )
        for key, value in clean.items():
            setattr(record, key, value)
        record.related_anomaly_id = related_anomaly_id
        record.updated_at = self.clock()
        self.session.flush()
        return record

    def get(self, record_id: int) -> MaintenanceEvent:
        record = self.session.get(MaintenanceEvent, record_id)
        if record is None:
            raise NotFoundError(f"Maintenance record {record_id} was not found.")
        return record

    def list(
        self,
        *,
        machine_id: str | None = None,
        event_type: str | None = None,
        window: Window | None = None,
        limit: int | None = 500,
    ) -> list[MaintenanceEvent]:
        stmt = select(MaintenanceEvent)
        if machine_id:
            stmt = stmt.where(MaintenanceEvent.machine_id == machine_id)
        if event_type:
            stmt = stmt.where(MaintenanceEvent.event_type == event_type)
        if window is not None:
            stmt = stmt.where(
                MaintenanceEvent.start_time >= window.start, MaintenanceEvent.start_time < window.end
            )
        stmt = stmt.order_by(MaintenanceEvent.start_time.desc(), MaintenanceEvent.id.desc())
        if limit is not None:
            stmt = stmt.limit(limit)
        return list(self.session.scalars(stmt))
